+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.HashSet;
+import java.util.List;
+import java.util.Set;
+
+/**
+ * Encapsulates filtering criteria for customers.
+ *
+ * @param nameTerms terms that must all appear in firstName or lastName (case and accent insensitive);
+ *                  empty list matches all customers
+ * @param statuses  customer statuses to include; empty set matches all statuses
+ */
+public record CustomerFilter(List<String> nameTerms, Set<CustomerStatus> statuses) {
+
+    public static CustomerFilter empty() {
+        return new CustomerFilter(List.of(), Set.of());
+    }
+
+    /**
+     * Creates a filter with the given name and statuses.
+     *
+     * @param name    space-separated name terms; null or empty matches all
+     * @param statuses comma-separated status names; empty matches all
+     */
+    public static CustomerFilter of(String name, String statuses) {
+        var terms = parseNameTerms(name);
+        var statusSet = parseStatuses(statuses);
+        return new CustomerFilter(terms, statusSet);
+    }
+
+    private static List<String> parseNameTerms(String name) {
+        if (name == null || name.isBlank()) {
+            return List.of();
+        }
+        return Arrays.stream(name.trim().split("\\s+"))
+                .map(CustomerFilter::normalize)
+                .toList();
+    }
+
+    private static Set<CustomerStatus> parseStatuses(String statuses) {
+        if (statuses == null || statuses.isBlank()) {
+            return Set.of();
+        }
+        Set<CustomerStatus> result = new HashSet<>();
+        for (String status : statuses.split(",")) {
+            result.add(CustomerStatus.valueOf(status.trim()));
+        }
+        return result;
+    }
+
+    public boolean matches(Customer customer) {
+        if (!matchesName(customer)) {
+            return false;
+        }
+        if (!matchesStatus(customer)) {
+            return false;
+        }
+        return true;
+    }
+
+    private boolean matchesName(Customer customer) {
+        if (nameTerms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        for (String term : nameTerms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        if (statuses.isEmpty()) {
+            return true;
+        }
+        return statuses.contains(customer.status());
+    }
+
+    private static String normalize(String s) {
+        if (s == null) {
+            return "";
+        }
+        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
+        return decomposed.replaceAll("\\p{Mn}", "").toLowerCase();
+    }
+}
